// reportUninstallOutcome prints the removal warnings, the recovery commands
// for plugins the user must run by hand, and the closing status line, and
// decides the exit code — all from the same sweep and removal results the
// confirmation summary was built from.
func reportUninstallOutcome(w, errW io.Writer, repoRoot string, hookState agentHookState, failedAgents []failedAgent, steps []removalStep, strict bool) error {
	for _, s := range steps {
		if s.err != nil {
			fmt.Fprintf(errW, "Warning: failed to remove %s: %v\n", s.subject, s.err)
		} else if s.removed != "" {
			fmt.Fprintf(w, "  Removed %s\n", s.removed)
		}
	}

	uncheckedPlugins := hookState.uncheckedExternal()
	var failedExternal, failedBuiltin []types.AgentName
	for _, f := range failedAgents {
		externalMark := ""
		if f.external {
			externalMark = " (external)"
		}
		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %s%s: %v\n", agentDisplayName(f.name), externalMark, f.err)
		if f.external {
			failedExternal = append(failedExternal, f.name)
		} else {
			failedBuiltin = append(failedBuiltin, f.name)
		}
	}
	// .entire/ — and with it the external_agents setting that gates discovery —
	// is already gone by the time this prints, so a re-run cannot even see these
	// plugins, let alone retry them. Name the command that still works, while it
	// can still be acted on, rather than leaving the user with a warning they
	// cannot act on. A built-in needs none of this: it is always reachable on a
	// re-run.
	for _, name := range failedExternal {
		fmt.Fprintf(errW, "  %s hooks are still installed. Remove them with:\n", agentDisplayName(name))
		fmt.Fprintf(errW, "    %s\n", pluginUninstallCommand(repoRoot, name))
	}
	// "may": we never found out whether this plugin has hooks, and we did not ask
	// it to remove them — asking a plugin that cannot answer to mutate state is
	// not something to do on the user's behalf. Only plugins appear here: a
	// built-in we could not check still had its removal attempted in-process, so
	// there is no command for the user to go run — its unverified state is
	// reported (and fails the command) below instead.
	for _, u := range uncheckedPlugins {
		fmt.Fprintf(errW, "  %s hooks may still be installed. Remove them with:\n", agentDisplayName(u.name))
		fmt.Fprintf(errW, "    %s\n", pluginUninstallCommand(repoRoot, u.name))
	}
	if len(failedExternal) > 0 || len(uncheckedPlugins) > 0 {
		fmt.Fprintln(errW, "  Re-running `entire disable --uninstall` will not reach these plugins once .entire/ is gone.")
	}

	// A built-in problem fails the command outright, in both modes: Entire owns
	// its built-ins, so a removal that failed or a check that could not run is
	// Entire's own uninstall not doing its job, and "uninstalled successfully"
	// would assert exactly what just failed. The remedy is not a plugin command —
	// it is fixing the file the warnings above name and re-running, which the
	// not-installed early return no longer cuts off.
	//
	// A failed removal subsumes a failed check (they read the same config file,
	// so the common cause — an unreadable file — trips both), hence the dedupe:
	// each agent is reported once, under the stronger of its two facts.
	failedSet := make(map[types.AgentName]bool, len(failedBuiltin))
	for _, name := range failedBuiltin {
		failedSet[name] = true
	}
	var verifyOnly []types.AgentName
	for _, u := range hookState.uncheckedInternal() {
		if !failedSet[u.name] {
			verifyOnly = append(verifyOnly, u.name)
		}
	}
	if len(failedBuiltin) > 0 || len(verifyOnly) > 0 {
		if len(failedBuiltin) > 0 {
			fmt.Fprintf(w, "\nEntire could not remove %s hooks - they may still be installed. See the warnings above.\n",
				strings.Join(agentDisplayNames(failedBuiltin), ", "))
		}
		if len(verifyOnly) > 0 {
			fmt.Fprintf(w, "\nEntire could not check whether %s hooks are installed - they may or may not remain. See the warnings above.\n",
				strings.Join(agentDisplayNames(verifyOnly), ", "))
		}
		return NewSilentError(errors.New("agent hooks could not be removed or verified"))
	}

	// Not "successfully": external agent hooks may be left behind, and they are
	// unreachable from a re-run now that .entire/ is gone, so the user has to act
	// on the warnings above.
	//
	// Whether that fails the command is the caller's call, not the plugin's. A
	// plugin is third-party code Entire cannot fix, so by default it does not get
	// to fail Entire's own uninstall; --strict opts into that.
	if len(failedExternal) > 0 || len(uncheckedPlugins) > 0 {
		fmt.Fprintln(w, "\nEntire CLI uninstalled, but some external agent hooks may remain - see the warnings above.")
		if strict {
			return NewSilentError(errors.New("some external agent hooks could not be removed"))
		}
		return nil
	}

	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
	return nil
}

