// external agent AreHooksInstalled is a subprocess, and it is also what the
// confirmation summary was built from, so reusing it uninstalls exactly what the
// user was shown.
//
// Each failed removal is returned with the agent's name, the reason, and
// whether it is an external plugin: the remedies differ (an external's hooks
// can only be removed by its plugin binary — which the caller is about to make
// undiscoverable — while a failed built-in is Entire's own removal not doing
// its job), and the caller is the one that decides what each kind means for
// output and exit code.
func removeAgentHooks(ctx context.Context, w io.Writer, installed []types.AgentName) []failedAgent {
	wasInstalled := make(map[types.AgentName]bool, len(installed))
	for _, name := range installed {
		wasInstalled[name] = true
	}

	var failed []failedAgent
	for _, name := range agent.List() {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		hs, ok := agent.AsHookSupport(ag)
		if !ok {
			continue
		}
		// Built-in agents get the call unconditionally: it is an in-process,
		// idempotent cleanup, and it still removes hooks a stale AreHooksInstalled
		// fails to recognize. For an external agent it is a subprocess running the
		// plugin's mutating uninstall-hooks, and discovery registered every
		// entire-agent-* binary on $PATH, not just the one the user enabled — so a
		// plugin reporting no hooks is left alone.
		if !wasInstalled[name] && external.IsExternal(ag) {
			// Covers both a plugin that cleanly reported no hooks and one that could
			// not answer; the sweep told them apart and the caller reports the
			// second kind, naming a command the user can run by hand. Either way we
			// do not ask a plugin to mutate state it never claimed to own.
			logging.Debug(ctx, "skipping external agent hook removal: plugin did not report hooks installed",
				"agent", string(name))
			continue
		}
		if err := hs.UninstallHooks(ctx); err != nil {
			failed = append(failed, failedAgent{name: name, err: err, external: external.IsExternal(ag)})
		} else if wasInstalled[name] {
			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
		}
	}
	return failed
}

// removeAllSessionStates removes all session state files and the directory.
func removeAllSessionStates(ctx context.Context) (int, error) {
	store, err := session.NewStateStore(ctx)
	if err != nil {
		return 0, fmt.Errorf("failed to create state store: %w", err)
	}

	// Count states before removing
	states, err := store.List(ctx)
	if err != nil {
		return 0, fmt.Errorf("failed to list session states: %w", err)
	}
	count := len(states)

	// Remove the entire directory
	if err := store.RemoveAll(); err != nil {
		return 0, fmt.Errorf("failed to remove session states: %w", err)
	}

	// Sweep the per-session advisory lock files. These live alongside the
	// state directory rather than inside it (see strategy.stateLockPath) so
	// session-listing code doesn't have to filter them out. Best-effort:
	// failing here doesn't undo the state-file removal.
	if commonDir, cdErr := strategy.GetGitCommonDir(ctx); cdErr == nil {
		_ = os.RemoveAll(filepath.Join(commonDir, "entire-session-locks"))
	}

	return count, nil
}

