func removeAgentHooks(ctx context.Context, repoRoot string, hookState agentHookState, strict bool) []removalStep {
	wasInstalled := make(map[types.AgentName]bool, len(hookState.installed))
	for _, name := range hookState.installed {
		wasInstalled[name] = true
	}

	var steps []removalStep
	failedBuiltin := make(map[types.AgentName]bool)
	externalProblem := false
	for _, name := range agent.List() {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		hs, ok := agent.AsHookSupport(ag)
		if !ok {
			continue
		}
		// Built-in agents get the call unconditionally: it is an in-process,
		// idempotent cleanup, and it still removes hooks a stale AreHooksInstalled
		// fails to recognize. For an external agent it is a subprocess running the
		// plugin's mutating uninstall-hooks, and discovery registered every
		// entire-agent-* binary on $PATH, not just the one the user enabled — so a
		// plugin reporting no hooks is left alone.
		if !wasInstalled[name] && external.IsExternal(ag) {
			// Covers both a plugin that cleanly reported no hooks and one that could
			// not answer; the sweep told them apart and the caller reports the
			// second kind, naming a command the user can run by hand. Either way we
			// do not ask a plugin to mutate state it never claimed to own.
			logging.Debug(ctx, "skipping external agent hook removal: plugin did not report hooks installed",
				"agent", string(name))
			continue
		}
		switch err := hs.UninstallHooks(ctx); {
		case err != nil && external.IsExternal(ag):
			externalProblem = true
			steps = append(steps, removalStep{
				failed: true,
				failure: fmt.Sprintf("Warning: failed to remove agent hooks: %s (external): %v\n  %s hooks are still installed. Remove them with:\n    %s",
					agentDisplayName(name), err, agentDisplayName(name), pluginUninstallCommand(repoRoot, name)),
				optional: !strict,
			})
		case err != nil:
			failedBuiltin[name] = true
			steps = append(steps, removalStep{
				failed:  true,
				failure: fmt.Sprintf("Warning: failed to remove agent hooks: %s: %v", agentDisplayName(name), err),
			})
		case wasInstalled[name]:
			steps = append(steps, removalStep{success: fmt.Sprintf("  Removed %s hooks", ag.Type())})
		}
	}

	for _, u := range hookState.unchecked {
		if u.external {
			// "may": we never found out whether this plugin has hooks, and we did
			// not ask it to remove them — asking a plugin that cannot answer to
			// mutate state is not something to do on the user's behalf.
			externalProblem = true
			steps = append(steps, removalStep{
				failed: true,
				failure: fmt.Sprintf("  %s hooks may still be installed. Remove them with:\n    %s",
					agentDisplayName(u.name), pluginUninstallCommand(repoRoot, u.name)),
				optional: !strict,
			})
			continue
		}
		// A built-in's failed removal subsumes its failed check (they read the
		// same config file, so the common cause — an unreadable file — trips
		// both), hence the dedupe: each agent is reported once, under the
		// stronger of its two facts.
		if failedBuiltin[u.name] {
			continue
		}
		steps = append(steps, removalStep{
			failed: true,
			failure: fmt.Sprintf("Warning: could not check whether %s hooks are installed - they may or may not remain: %v",
				agentDisplayName(u.name), u.err),
		})
	}

	if externalProblem {
		// A note, not a failure of its own — optional so it can never be the
		// reason the uninstall fails; it only rides along with the external
		// problems that made it relevant.
		steps = append(steps, removalStep{
			failed:   true,
			failure:  "  Re-running `entire disable --uninstall` will not reach these plugins once .entire/ is gone.",
			optional: true,
		})
	}
	return steps
}

