// forEachHookAgent calls fn once per registered agent that supports hooks, in
// registry order. HookSupport embeds Agent, so fn needs no separate Agent
// argument. It is the single registry walk shared by the hooks-installed sweep
// and hook removal, so the two always agree on the universe of agents.
func forEachHookAgent(fn func(name types.AgentName, hs agent.HookSupport)) {
	for _, name := range agent.List() {
		ag, err := agent.Get(name)
		if err != nil {
			continue
		}
		hs, ok := agent.AsHookSupport(ag)
		if !ok {
			continue
		}
		fn(name, hs)
	}
}

